package ssh

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"
)

type fixtureCarrierCall struct {
	Argv  []string `json:"argv"`
	Stdin string   `json:"stdin"`
}
type fixtureCarrierRecord struct {
	Key   string               `json:"key"`
	Value string               `json:"value"`
	Calls []fixtureCarrierCall `json:"calls"`
}
type fixtureCarrierTrace struct {
	SchemaVersion int                    `json:"schema_version"`
	Records       []fixtureCarrierRecord `json:"records"`
}

// This golden is generated by the real Provider.SetMeta. Only the connection
// primitive is recorded; no substitute metadata protocol is manufactured.
func TestFixtureNativeMetadataCarrierTrace(t *testing.T) {
	trace := fixtureCarrierTrace{SchemaVersion: 1}
	tags := regexp.MustCompile(`GC_EOF_[0-9A-F]{16}`)
	for _, pair := range [][2]string{{"GC_DRAIN_ACK", "1"}, {"GC_DRAIN_ACK_SOURCE", "agent"}, {"GC_DRAIN_ACK_REQUESTER_INSTANCE_TOKEN", strings.Repeat("a", 64)}} {
		f := &fakeRunner{respond: answerStaging(nil)}
		if err := providerWith(f).SetMeta("queue-fixture-runtime", pair[0], pair[1]); err != nil {
			t.Fatal(err)
		}
		if len(f.calls) != 3 || !slices.Equal(f.calls[0], []string{"sh"}) || !slices.Equal(f.calls[1], []string{"tmux", "source-file", stagedDir + "/session.tmux"}) || !slices.Equal(f.calls[2], []string{"rm", "-rf", stagedDir}) {
			t.Fatal("native metadata carrier shape changed; review fixture protocol")
		}
		rec := fixtureCarrierRecord{Key: pair[0], Value: pair[1]}
		for i, args := range f.calls {
			rec.Calls = append(rec.Calls, fixtureCarrierCall{Argv: args, Stdin: tags.ReplaceAllString(string(f.stdins[i]), "GC_EOF_FIXTURE")})
		}
		trace.Records = append(trace.Records, rec)
	}
	raw, err := json.MarshalIndent(trace, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	if output := os.Getenv("GC_FIXTURE_TRACE_OUTPUT"); output != "" {
		if !filepath.IsAbs(output) {
			t.Fatal("trace output must be absolute")
		}
		if err = os.WriteFile(output, raw, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile("testdata/fixture-metadata-carrier.json")
	if err != nil {
		t.Fatal("actual native trace generated; reviewed golden absent:", err)
	}
	if string(raw) != string(want) {
		t.Fatal("native metadata trace drift; fixture acceptance must be reviewed")
	}
}
